#!/usr/bin/python3
"""One root-owned exclusive screen. Do not run from a working child lane."""
import hashlib
import json
import math
import os
from pathlib import Path
import subprocess
import sys
import time

ART = Path('/private/tmp/decoder-entropy-dataflow-20261018')
WT = Path('/Users/thesyncim/.codex/worktrees/decoder-entropy-dataflow/goav1')
WRAPPER = '/Users/thesyncim/.codex/bin/project-env'
CORPUS = '/Users/thesyncim/GolandProjects/goav1/testdata/benchcorpus'
BINS = {
    'A': Path('/private/tmp/decoder-grain-direct-20261018/candidate-integrated.test'),
    'B': ART / 'candidate-v2.test',
}
HASHES = {
    'A': '893ba02c9e349ca59be930c774a7d3e433f7a9444731027e899ee1f05fa98ee1',
    'B': '5ece62bbb086c4840aeed2de34de63c376551d99c03b4721e0f3b46c543438f0',
}
CASES = ['p360_intra_q32', 'p720_inter_q32']
ORDERS = ['AB', 'BA', 'AB']
OPS = 10


def save(path, value):
    path.write_text(json.dumps(value, indent=2) + '\n')


def parse(output, case):
    rows = [s.split() for s in output.splitlines()
            if s.startswith('BenchmarkPublicDecoderFullClip/')]
    if len(rows) != 1:
        raise RuntimeError(f'expected one benchmark row, got {len(rows)}')
    parts = rows[0]
    want = f'BenchmarkPublicDecoderFullClip/{case}/warm_reset_decode'
    if parts[0] not in (want, want + '-1') or int(parts[1]) != OPS:
        raise RuntimeError(f'unexpected benchmark case/count: {parts[:2]}')
    if len(parts[2:]) % 2:
        raise RuntimeError(f'unpaired metric columns: {parts}')
    metrics = {parts[i + 1]: float(parts[i]) for i in range(2, len(parts), 2)}
    if metrics.get('frames/op') != 48 or metrics.get('allocs/op') != 0:
        raise RuntimeError(f'frame/allocation guard failed: {metrics}')
    if 'B/op' not in metrics:
        raise RuntimeError(f'missing separately reported byte metric: {metrics}')
    if metrics.get('ns/op', 0) <= 0:
        raise RuntimeError(f'missing time: {metrics}')
    return metrics


def main():
    if os.environ.get('RUN_EXCLUSIVE_SCREEN') != '1':
        sys.exit('Root must explicitly set RUN_EXCLUSIVE_SCREEN=1 after all lanes are quiet.')
    for label, binary in BINS.items():
        digest = hashlib.sha256(binary.read_bytes()).hexdigest()
        if digest != HASHES[label]:
            sys.exit(f'{label} binary identity mismatch: {digest}')
    manifest = json.loads((ART / 'manifest-v2.json').read_text())
    script_digest = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    if script_digest != manifest['screen_script_sha256']:
        sys.exit(f'Frozen screen script identity mismatch: {script_digest}')
    for rel, expected in manifest['source_sha256'].items():
        for source in (WT / rel, ART / 'source-v2' / rel):
            digest = hashlib.sha256(source.read_bytes()).hexdigest()
            if digest != expected:
                sys.exit(f'Frozen source identity mismatch: {source}: {digest}')
    if not manifest.get('all_mandatory_gates_passed'):
        sys.exit('Mandatory exactness gates are not complete.')
    if not manifest.get('correctness_gates', {}).get('exact_warm_allocations', {}).get('passed'):
        sys.exit('Existing exact warm AllocsPerRun gate is not complete.')
    out = ART / 'screen-v2'
    if out.exists():
        sys.exit('The one frozen screen has already started; preserve its rows, do not resample.')
    out.mkdir()
    env = os.environ.copy()
    env.update({
        'CODEX_AGENT_ID': 'astra_decoder_entropy_gap',
        'CODEX_PROJECT_CACHE_ROOT': '/private/var/folders/x3/kqy4mlzx43n21g8wpjj2hp580000gn/C/codex-projects',
        'GOEXPERIMENT': 'simd',
        'GOAV1_BENCH_CORPUS_DIR': CORPUS,
        'GOMAXPROCS': '1',
        'GOGC': '100',
    })
    rows = []
    save(out / 'protocol.json', {
        'script_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
        'binary_sha256': HASHES, 'cases': CASES, 'orders': ORDERS, 'ops': OPS,
        'guards': manifest['planned_promotion_guard'], 'base_commit': manifest['base_commit'],
        'started_unix': time.time(), 'environment': {k: env[k] for k in (
            'CODEX_AGENT_ID', 'CODEX_PROJECT_CACHE_ROOT', 'GOEXPERIMENT',
            'GOAV1_BENCH_CORPUS_DIR', 'GOMAXPROCS', 'GOGC')},
    })
    for case in CASES:
        for pair, order in enumerate(ORDERS, 1):
            for label in order:
                cmd = [WRAPPER, str(BINS[label]), '-test.run=^$', '-test.count=1',
                       '-test.cpu=1', '-test.benchmem', f'-test.benchtime={OPS}x',
                       f'-test.bench=^BenchmarkPublicDecoderFullClip$/^{case}$/^warm_reset_decode$']
                run = subprocess.run(cmd, cwd=WT, env=env, text=True,
                                     stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
                log = out / f'{case}-pair{pair}-{label}.txt'
                log.write_text(run.stdout)
                row = {'case': case, 'pair': pair, 'label': label, 'command': cmd,
                       'returncode': run.returncode, 'log': str(log)}
                if run.returncode:
                    rows.append(row)
                    save(out / 'rows.json', rows)
                    raise RuntimeError(f'benchmark process failed; see {log}')
                row['metrics'] = parse(run.stdout, case)
                rows.append(row)
                save(out / 'rows.json', rows)
                print(case, pair, label, row['metrics'], flush=True)
    summary = {}
    for case in CASES:
        ratios = []
        for pair in range(1, 4):
            group = {r['label']: r['metrics']['ns/op'] for r in rows
                     if r['case'] == case and r['pair'] == pair}
            ratios.append(group['B'] / group['A'])
        ratio = math.exp(sum(math.log(r) for r in ratios) / len(ratios))
        summary[case] = {'paired_candidate_over_baseline': ratios,
                         'geomean_ratio': ratio, 'saving_fraction': 1 - ratio,
                         'faster_pairs': sum(r < 1 for r in ratios)}
    primary, secondary = (summary[c] for c in CASES)
    summary['promotion_guard_pass'] = (primary['saving_fraction'] >= 0.005
        and primary['faster_pairs'] >= 2 and secondary['geomean_ratio'] <= 1.01)
    summary['interpretation'] = 'One predeclared full-clip screen; no native-stage attribution or unchanged resampling.'
    save(out / 'summary.json', summary)
    print(json.dumps(summary, indent=2), flush=True)


if __name__ == '__main__':
    main()

