package tile

import (
	"github.com/thesyncim/goav1/internal/av1/quantize"
	"github.com/thesyncim/goav1/internal/av1/transform"
	"math/rand"
	"slices"
	"testing"
)

// Frozen b9e260f4 tracked path. Test-only overlay kept with experiment evidence.
func (s *DecodeState) readCoefficientsTXBTracked2DFrozenB9(cdfs *CoeffCDFs, req TXBDecodeRequest, coeffs []int16, scan []int16, levelsScratch []uint8, geo *coeffGeometry) (TXBDecodeResult, error) {
	if s == nil || geo == nil {
		return TXBDecodeResult{}, ErrInvalidDecodeState
	}
	maxEOB := int(geo.maxEOB)
	if len(coeffs) < maxEOB || len(scan) < maxEOB {
		return TXBDecodeResult{}, ErrInvalidDecodeState
	}
	coeffs = coeffs[:maxEOB]
	scan = scan[:maxEOB]
	scratchLen := int(geo.scratchLen)
	if len(levelsScratch) < scratchLen {
		return TXBDecodeResult{}, ErrInvalidDecodeState
	}
	levelsScratch = levelsScratch[:scratchLen]
	if req.Size >= transformSizeCount || !req.Plane.Valid() || req.Class != transform.Class2D || !req.knownNonZero || !req.trustedScan {
		return TXBDecodeResult{}, ErrInvalidDecodeState
	}
	dirtyArr := req.coeffDirtyPos
	dirtyLen := req.coeffDirtyLen
	levelDirtyArr := req.levelDirtyPos
	levelDirtyLen := req.levelDirtyLen
	if dirtyArr == nil || dirtyLen == nil || levelDirtyArr == nil || levelDirtyLen == nil || *dirtyLen != 0 {
		return TXBDecodeResult{}, ErrInvalidDecodeState
	}
	if !req.skipNonZeroCoeffClear {
		clear(coeffs[:maxEOB])
	}

	scanHotSlice := coeffScanHotTable[req.Size][transform.Class2D]
	if len(scanHotSlice) < maxEOB {
		return TXBDecodeResult{}, ErrInvalidDecodeState
	}
	scanHotSlice = scanHotSlice[:maxEOB]
	txCtx := int(geo.txCtx)
	txBR := int(geo.txBRCtx)
	if cdfs == nil || txCtx >= CoeffTxSizeContexts || txBR >= CoeffTxSizeContexts ||
		req.DCSignContext >= 3 ||
		req.EOBMultiContext >= maxEOBFlagContexts {
		return TXBDecodeResult{}, ErrInvalidDecodeState
	}
	baseArr := &cdfs.CoeffBase[txCtx][req.Plane]
	baseEOBArr := &cdfs.CoeffBaseEOB[txCtx][req.Plane]
	brArr := &cdfs.CoeffBR[txBR][req.Plane]
	eobCDF := eobFlagCDFKnown(cdfs, req.Size, req.Plane, req.EOBMultiContext)
	eobSymbols := int(eobMultiSizeTable[req.Size]) + 5
	eobExtraArr := &cdfs.EOBExtra[txCtx][req.Plane]
	dcSignCDF := &cdfs.DCSign[req.Plane][req.DCSignContext]
	cdfUpdate := s.Reader.AllowCDFUpdate()
	reader := s.Reader.Cursor()
	eob, err := readEOBCursorKnown(&reader, eobCDF, eobSymbols, eobExtraArr)
	if err != nil {
		reader.CommitStateTo(&s.Reader)
		return TXBDecodeResult{}, err
	}
	eobPos := int(eob.Position)
	if eobPos <= 0 || eobPos > maxEOB {
		reader.CommitStateTo(&s.Reader)
		return TXBDecodeResult{}, ErrInvalidDecodeState
	}
	lastC := eobPos - 1
	lastHot := scanHotSlice[lastC]
	lastPos := int(lastHot.Pos)
	lastLevel := reader.ReadCDF3Unchecked(&baseEOBArr[lastHot.LowerEOBCtx]) + 1
	lastPackedLevel := uint8(lastLevel * 0x41)
	if lastLevel > NumBaseLevels {
		var extra uint8
		if cdfUpdate {
			extra = readBaseRangeFromArrCursorUpdateTrusted(&reader, brArr, int(lastHot.BREOBCtx))
		} else {
			extra = readBaseRangeFromArrCursorNoUpdateTrusted(&reader, brArr, int(lastHot.BREOBCtx))
		}
		lastLevel += int(extra)
		lastPackedLevel = uint8(lastLevel | 0xc0)
	}
	if eobPos == 1 {
		if coeffTraceEnabled {
			coeffTraceBlock(int(req.Plane), 0, 0, int(req.Size), int(req.Class), eobPos)
		}
		negative := reader.ReadBinaryCDFUnchecked(dcSignCDF) != 0
		baseLevel := lastLevel
		golombExtra := 0
		if lastLevel >= MaxBaseBRRange {
			tail, err := readCoeffGolombCursor(&reader)
			if err != nil {
				reader.CommitStateTo(&s.Reader)
				return TXBDecodeResult{}, err
			}
			golombExtra = tail
			lastLevel += tail
		}
		signBit := 0
		if negative {
			signBit = 1
		}
		if coeffTraceEnabled {
			coeffTraceCoeff(0, lastPos, baseLevel, golombExtra, lastLevel, signBit)
		}
		if lastLevel > int(^uint16(0)>>1) {
			reader.CommitStateTo(&s.Reader)
			return TXBDecodeResult{}, ErrInvalidDecodeState
		}
		dequantTarget, dequantTxScale, dqMax := prepareTrackedCoeffDequant(req.dequant, req.dequantPlane, geo)
		if dequantTarget != nil {
			if !req.dequantDCOnly {
				clear(dequantTarget.Dst[:maxEOB])
			}
			dcFactor := dequantTarget.Factors[req.dequantPlane][0]
			dequantTarget.Dst[lastPos] = quantize.DequantizeMagnitudeWithBoundsTrusted(int32(lastLevel), negative, dcFactor, dequantTxScale, dqMax)
			dequantTarget.ActiveRows = (lastPos & (int(geo.scanHeight) - 1)) + 1
			dequantTarget.TxScale = dequantTxScale
			dequantTarget.decoded = true
		} else {
			signed := int16(lastLevel)
			if negative {
				signed = -signed
			}
			coeffs[lastPos] = signed
			dirtyArr[0] = int16(lastPos)
			*dirtyLen = 1
		}

		culLevel := lastLevel
		if culLevel > CoeffContextMask {
			culLevel = CoeffContextMask
		}
		if lastLevel != 0 {
			if negative {
				culLevel |= 1 << CoeffContextBits
			} else {
				culLevel += 2 << CoeffContextBits
			}
		}
		if coeffTraceEnabled {
			coeffTraceCulLevel(culLevel)
		}
		reader.CommitStateTo(&s.Reader)
		return TXBDecodeResult{
			EOB:         1,
			MaxScanLine: uint16(lastPos),
			CulLevel:    uint8(culLevel),
		}, nil
	}

	levelClearScratch := levelsScratch
	if req.levelDirtyScratch != nil {
		levelClearScratch = req.levelDirtyScratch[:]
	}
	for i := 0; i < int(*levelDirtyLen); i++ {
		padded := int(levelDirtyArr[i])
		if uint(padded) < uint(len(levelClearScratch)) {
			levelClearScratch[padded] = 0
		}
	}
	*levelDirtyLen = 0
	levelDirtyNext := 0
	lastPadded := int(lastHot.Padded)
	levelsScratch[lastPadded] = lastPackedLevel
	levelDirtyArr[levelDirtyNext] = int16(lastPadded)
	levelDirtyNext++
	dirtyArr[0] = packCoeffDirty(lastPos, lastLevel)
	nonzeroScanLen := 1

	stride := int(geo.stride)
	if cdfUpdate {
		for c := eobPos - 2; c >= 1; c-- {
			p := scanHotSlice[c]
			pos := int(p.Pos)
			padded := int(p.Padded)
			s1 := padded + stride
			s1p1 := s1 + 1
			s2 := s1 + stride
			p1 := padded + 1
			p2 := padded + 2
			_ = levelsScratch[s2]
			_ = levelsScratch[p2]
			// Tracked 2D levels store the raw token in bits 0..5 and
			// min(token, 3) in bits 6..7. Summing the five packed neighbors
			// makes the rounded half-sum of clipped levels available in bits
			// 7 and above. If the clipped sum is below 8, the raw sum cannot
			// carry into that field; otherwise the context saturates at 4.
			h := int(levelsScratch[s1]) + int(levelsScratch[p1]) + int(levelsScratch[s1p1])
			l := h + int(levelsScratch[s2]) + int(levelsScratch[p2])
			ctx := (l + 64) >> 7
			if ctx > 4 {
				ctx = 4
			}
			ctx += int(p.Lower2DOffset)
			level := reader.ReadCDF4UpdateUnchecked(&baseArr[ctx])
			packedLevel := uint8(level * 0x41)
			if level == NumBaseLevels+1 {
				// Re-read only on the rare high-token path so h does not need
				// to stay live across the CDF update call. The low six bits
				// recover the raw-token sum (at most 45).
				brH := (int(levelsScratch[s1]) + int(levelsScratch[p1]) + int(levelsScratch[s1p1])) & 63
				mag := (brH + 1) >> 1
				if mag > 6 {
					mag = 6
				}
				brCtx := mag + int(p.BR2DOffset)
				extra := readBaseRangeFromArrCursorUpdateTrusted(&reader, brArr, brCtx)
				level += int(extra)
				packedLevel = uint8(level | 0xc0)
			}
			if level != 0 {
				levelsScratch[padded] = packedLevel
				levelDirtyArr[levelDirtyNext] = int16(padded)
				levelDirtyNext++
				dirtyArr[nonzeroScanLen] = packCoeffDirty(pos, level)
				nonzeroScanLen++
			}
		}
	} else {
		for c := eobPos - 2; c >= 1; c-- {
			p := scanHotSlice[c]
			pos := int(p.Pos)
			padded := int(p.Padded)
			s1 := padded + stride
			s1p1 := s1 + 1
			s2 := s1 + stride
			p1 := padded + 1
			p2 := padded + 2
			_ = levelsScratch[s2]
			_ = levelsScratch[p2]
			h := int(levelsScratch[s1]) + int(levelsScratch[p1]) + int(levelsScratch[s1p1])
			l := h + int(levelsScratch[s2]) + int(levelsScratch[p2])
			ctx := (l + 64) >> 7
			if ctx > 4 {
				ctx = 4
			}
			ctx += int(p.Lower2DOffset)
			level := reader.ReadCDF4NoUpdateUnchecked(&baseArr[ctx])
			packedLevel := uint8(level * 0x41)
			if level == NumBaseLevels+1 {
				brH := (int(levelsScratch[s1]) + int(levelsScratch[p1]) + int(levelsScratch[s1p1])) & 63
				mag := (brH + 1) >> 1
				if mag > 6 {
					mag = 6
				}
				brCtx := mag + int(p.BR2DOffset)
				extra := readBaseRangeFromArrCursorNoUpdateTrusted(&reader, brArr, brCtx)
				level += int(extra)
				packedLevel = uint8(level | 0xc0)
			}
			if level != 0 {
				levelsScratch[padded] = packedLevel
				levelDirtyArr[levelDirtyNext] = int16(padded)
				levelDirtyNext++
				dirtyArr[nonzeroScanLen] = packCoeffDirty(pos, level)
				nonzeroScanLen++
			}
		}
	}
	dcHot := scanHotSlice[0]
	dcPadded := int(dcHot.Padded)
	var dcLevel int
	var packedDCLevel uint8
	if cdfUpdate {
		dcLevel = reader.ReadCDF4UpdateUnchecked(&baseArr[0])
		packedDCLevel = uint8(dcLevel * 0x41)
		if dcLevel == NumBaseLevels+1 {
			s1 := dcPadded + stride
			s1p1 := s1 + 1
			p1 := dcPadded + 1
			_ = levelsScratch[s1p1]
			h := int(levelsScratch[p1]) + int(levelsScratch[s1]) + int(levelsScratch[s1p1])
			mag := ((h & 63) + 1) >> 1
			if mag > 6 {
				mag = 6
			}
			brCtx := mag + int(dcHot.BR2DOffset)
			extra := readBaseRangeFromArrCursorUpdateTrusted(&reader, brArr, brCtx)
			dcLevel += int(extra)
			packedDCLevel = uint8(dcLevel | 0xc0)
		}
	} else {
		dcLevel = reader.ReadCDF4NoUpdateUnchecked(&baseArr[0])
		packedDCLevel = uint8(dcLevel * 0x41)
		if dcLevel == NumBaseLevels+1 {
			s1 := dcPadded + stride
			s1p1 := s1 + 1
			p1 := dcPadded + 1
			_ = levelsScratch[s1p1]
			h := int(levelsScratch[p1]) + int(levelsScratch[s1]) + int(levelsScratch[s1p1])
			mag := ((h & 63) + 1) >> 1
			if mag > 6 {
				mag = 6
			}
			brCtx := mag + int(dcHot.BR2DOffset)
			extra := readBaseRangeFromArrCursorNoUpdateTrusted(&reader, brArr, brCtx)
			dcLevel += int(extra)
			packedDCLevel = uint8(dcLevel | 0xc0)
		}
	}
	if dcLevel != 0 {
		levelsScratch[dcPadded] = packedDCLevel
		levelDirtyArr[levelDirtyNext] = int16(dcPadded)
		levelDirtyNext++
		dirtyArr[nonzeroScanLen] = packCoeffDirty(0, dcLevel)
		nonzeroScanLen++
	}
	*levelDirtyLen = uint16(levelDirtyNext)

	if coeffTraceEnabled {
		coeffTraceBlock(int(req.Plane), 0, 0, int(req.Size), int(req.Class), eobPos)
	}
	dequantTarget, dequantTxScale, dqMax := prepareTrackedCoeffDequant(req.dequant, req.dequantPlane, geo)
	var dcFactor, acFactor int32
	activeRowMask := 0
	if dequantTarget != nil {
		factors := dequantTarget.Factors[req.dequantPlane]
		dcFactor, acFactor = factors[0], factors[1]
		activeRowMask = int(geo.scanHeight) - 1
		clear(dequantTarget.Dst[:maxEOB])
	}
	culLevel := 0
	dcValue := 0
	maxScanLine := 0
	activeRows := 0
	i := nonzeroScanLen - 1
	if i >= 0 && coeffDirtyPackedPos(dirtyArr[i]) == 0 {
		pos := 0
		level := int(uint16(dirtyArr[i]) >> 10)
		negative := reader.ReadBinaryCDFUnchecked(dcSignCDF) != 0
		baseLevel := level
		golombExtra := 0
		if level >= MaxBaseBRRange {
			tail, err := readCoeffGolombCursor(&reader)
			if err != nil {
				reader.CommitStateTo(&s.Reader)
				return TXBDecodeResult{}, err
			}
			golombExtra = tail
			level += tail
		}
		signBit := 0
		if negative {
			signBit = 1
		}
		if coeffTraceEnabled {
			c := coeffTraceScanIndex(scan, pos, eobPos)
			coeffTraceCoeff(c, pos, baseLevel, golombExtra, level, signBit)
		}
		culLevel += level
		if level > int(^uint16(0)>>1) {
			reader.CommitStateTo(&s.Reader)
			return TXBDecodeResult{}, ErrInvalidDecodeState
		}
		if dequantTarget != nil {
			dequantTarget.Dst[pos] = quantize.DequantizeMagnitudeWithBoundsTrusted(int32(level), negative, dcFactor, dequantTxScale, dqMax)
			row := pos & activeRowMask
			if row+1 > activeRows {
				activeRows = row + 1
			}
			if level != 0 {
				dcValue = 1
				if negative {
					dcValue = -1
				}
			}
		} else {
			signed := int16(level)
			if negative {
				signed = -signed
			}
			dcValue = int(signed)
			coeffs[pos] = signed
			dirtyArr[i] = int16(pos)
		}
		i--
	}
	for ; i >= 0; i-- {
		packed := uint16(dirtyArr[i])
		pos := int(packed) & coeffDirtyPosMask
		level := int(packed >> 10)
		if pos > maxScanLine {
			maxScanLine = pos
		}
		bit, refill := reader.ReadBitNoRefillTrusted()
		if refill {
			reader.RefillTrusted()
		}
		negative := bit != 0
		baseLevel := level
		golombExtra := 0
		if level >= MaxBaseBRRange {
			tail, err := readCoeffGolombCursor(&reader)
			if err != nil {
				reader.CommitStateTo(&s.Reader)
				return TXBDecodeResult{}, err
			}
			golombExtra = tail
			level += tail
		}
		signBit := 0
		if negative {
			signBit = 1
		}
		if coeffTraceEnabled {
			c := coeffTraceScanIndex(scan, pos, eobPos)
			coeffTraceCoeff(c, pos, baseLevel, golombExtra, level, signBit)
		}
		culLevel += level
		if level > int(^uint16(0)>>1) {
			reader.CommitStateTo(&s.Reader)
			return TXBDecodeResult{}, ErrInvalidDecodeState
		}
		if dequantTarget != nil {
			dequantTarget.Dst[pos] = quantize.DequantizeMagnitudeWithBoundsTrusted(int32(level), negative, acFactor, dequantTxScale, dqMax)
			row := pos & activeRowMask
			if row+1 > activeRows {
				activeRows = row + 1
			}
		} else {
			signed := int16(level)
			if negative {
				signed = -signed
			}
			coeffs[pos] = signed
			dirtyArr[i] = int16(pos)
		}
	}
	if dequantTarget != nil {
		*dirtyLen = 0
		dequantTarget.ActiveRows = activeRows
		dequantTarget.TxScale = dequantTxScale
		dequantTarget.decoded = true
	} else {
		*dirtyLen = uint16(nonzeroScanLen)
	}

	if culLevel > CoeffContextMask {
		culLevel = CoeffContextMask
	}
	if dcValue < 0 {
		culLevel |= 1 << CoeffContextBits
	} else if dcValue > 0 {
		culLevel += 2 << CoeffContextBits
	}

	if coeffTraceEnabled {
		coeffTraceCulLevel(culLevel)
	}
	reader.CommitStateTo(&s.Reader)
	return TXBDecodeResult{
		EOB:         uint16(eobPos),
		MaxScanLine: uint16(maxScanLine),
		CulLevel:    uint8(culLevel),
	}, nil
}

func TestTracked2DFrozenErrorScratch(t *testing.T) {
	random := rand.New(rand.NewSource(0xcdf4b9))
	errors, acErrors, successes := 0, 0, 0
	for _, size := range []TransformSize{TransformSize4x4, TransformSize8x8, TransformSize16x16, TransformSize32x32, TransformSize64x64} {
		for sample := 0; sample < 16; sample++ {
			payload := txbDiffPayload(random, sample)
			if sample == 0 {
				payload = make([]byte, 128)
			}
			var cdfs CoeffCDFs
			if err := cdfs.InitDefault(80); err != nil {
				t.Fatal(err)
			}
			if sample%2 == 0 {
				seedGolombHeavyCDFs(t, random, &cdfs)
			} else {
				scrambleCoeffCDFs(t, random, &cdfs)
			}
			got := newTXBDiffState(t, payload, size, transform.Class2D, &cdfs, true)
			want := newTXBDiffState(t, payload, size, transform.Class2D, &cdfs, true)
			for block := 0; block < 12; block++ {
				dcCtx, eobCtx := uint8(random.Intn(3)), uint8(random.Intn(2))
				run := func(st *txbDiffState, old bool) (TXBDecodeResult, error) {
					for i := 0; i < int(st.dirtyLen); i++ {
						st.coeffs[coeffDirtyPackedPos(st.dirty[i])] = 0
					}
					st.dirtyLen = 0
					req := TXBDecodeRequest{Size: size, Plane: CoeffPlaneY, Class: transform.Class2D, DCSignContext: dcCtx, EOBMultiContext: eobCtx, knownNonZero: true, trustedScan: true, skipNonZeroCoeffClear: true, coeffDirtyPos: &st.dirty, coeffDirtyLen: &st.dirtyLen, levelDirtyPos: &st.levelDirty, levelDirtyLen: &st.levelDirtyLen, levelDirtyScratch: &st.levelScratch}
					geo, _ := coeffGeoPtr(size)
					if old {
						return st.state.readCoefficientsTXBTracked2DFrozenB9(&st.cdfs, req, st.coeffs, st.scan, st.levels, geo)
					}
					return st.state.readCoefficientsTXBTracked2DWithGeo(&st.cdfs, req, st.coeffs, st.scan, st.levels, geo)
				}
				gr, ge := run(got, false)
				wr, we := run(want, true)
				if (ge == nil) != (we == nil) || (ge != nil && ge.Error() != we.Error()) || gr != wr || got.state.Reader.State() != want.state.Reader.State() || got.cdfs != want.cdfs || !slices.Equal(got.coeffs, want.coeffs) || got.dirty != want.dirty || got.dirtyLen != want.dirtyLen || got.levelDirty != want.levelDirty || got.levelDirtyLen != want.levelDirtyLen || got.levelScratch != want.levelScratch {
					t.Fatalf("size=%d sample=%d block=%d full/error state mismatch got=%v want=%v", size, sample, block, ge, we)
				}
				if ge != nil {
					errors++
					if got.levelDirtyLen > 2 {
						acErrors++
					}
					break
				}
				successes++
			}
		}
	}
	if errors == 0 || acErrors == 0 || successes == 0 {
		t.Fatalf("coverage errors=%d acErrors=%d successes=%d", errors, acErrors, successes)
	}
	t.Logf("full frozen state: errors=%d AC errors=%d successes=%d", errors, acErrors, successes)
}

